"""Hermes plugin using the native terminal provider ABC and toolset resolver."""
import json
from pathlib import Path
import subprocess
import sys

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from seatbelt.context import Context
from agent.terminal_env_provider import TerminalEnvironmentProvider
from hermes_constants import get_hermes_home
from tools.environments.local import LocalEnvironment


def browser_tools():
    context=Context(get_hermes_home())
    config=Path(context.settings['transport_home'])/'.clanker-cloud/config.json'
    if config.exists() and json.loads(config.read_text()).get('enabled'):
        from cloud_browser.tools import TOOLS
        return TOOLS
    return ['browser_exec']


class SeatbeltEnvironment(LocalEnvironment):
    _sudo_nopasswd_probe_supported = False

    def __init__(self, *, cwd, timeout):
        self.execution = Context(get_hermes_home())
        base = self.execution.home / "workspace"
        path = Path(cwd).resolve() if cwd else base
        if not any(path.is_relative_to(root) for root in (base, self.execution.home / "artifacts")):
            raise RuntimeError("Terminal cwd is outside this context")
        super().__init__(cwd=str(path), timeout=timeout,
                         env={"TERMINAL_TEMP_DIR": str(self.execution.terminal)})

    def get_temp_dir(self):
        return str(self.execution.terminal)

    def _run_bash(self, cmd_string, *, login=False, timeout=120, stdin_data=None):
        context = Context(self.execution.home)
        env = context.safe_env()
        env["TERMINAL_TEMP_DIR"] = str(context.terminal)
        proc = subprocess.Popen(context.command(["/bin/bash", "-c", cmd_string]),
                                env=env, cwd=self.cwd, text=True, encoding="utf-8", errors="replace",
                                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                stdin=subprocess.PIPE if stdin_data is not None else subprocess.DEVNULL,
                                start_new_session=True, close_fds=True)
        if stdin_data is not None:
            from tools.environments.base_output import _pipe_stdin
            _pipe_stdin(proc, stdin_data)
        return proc


class SeatbeltProvider(TerminalEnvironmentProvider):
    name = "clanker_seatbelt"
    display_name = "Clanker macOS Seatbelt"
    is_remote = False
    is_container = False

    def is_available(self):
        try:
            Context(get_hermes_home())
            return True
        except Exception:
            return False

    def create_environment(self, *, cwd, timeout, **kwargs):
        return SeatbeltEnvironment(cwd=cwd, timeout=timeout)


def gate(tool_name, args, next_call, **kwargs):
    try:
        context = Context(get_hermes_home())
        from vault.tools import TOOLS as vault_tools
        if tool_name in vault_tools or tool_name in browser_tools() and tool_name!='browser_exec':
            return next_call(args)
        if tool_name not in {"browser_exec", "terminal"}:
            return json.dumps({"success": False, "error": "Tool is outside this context's browser policy"})
        allowed = ({'code', 'session', 'timeout_s'} if tool_name == 'browser_exec' else
                   {'command', 'timeout', 'background', 'workdir', 'pty', 'notify_on_complete', 'watch_patterns', 'heartbeat'})
        if set(args) - allowed:
            return json.dumps({'success': False, 'error': 'Unsupported execution arguments'})
        if not context.settings.get('activated'):
            return json.dumps({'success': False, 'error': 'Execution unavailable: operator acceptance is pending'})
        if tool_name == "terminal" and args.get("background"):
            return json.dumps({"success": False, "error": "Use foreground terminal calls in the current browser POC"})
        if tool_name == 'terminal' and args.get('pty'):
            return json.dumps({'success': False, 'error': 'PTY execution is unavailable in the current browser POC'})
        return next_call(args)
    except Exception as error:
        return json.dumps({"success": False, "error": "Execution unavailable: " + str(error)})


def register(ctx):
    from toolsets import create_custom_toolset
    from vault.tools import register_tools, TOOLS as vault_tools
    ctx.register_terminal_environment_provider(SeatbeltProvider())
    from vault.service import on_gateway_control
    ctx.register_hook('on_gateway_control', on_gateway_control)
    register_tools(ctx)
    selected=browser_tools()
    if selected!=['browser_exec']:
        from cloud_browser.tools import register_tools as register_cloud
        register_cloud(ctx)
    create_custom_toolset("clanker_browser", "Browser and private access", tools=[*selected, "terminal", *vault_tools])
    ctx.register_middleware("tool_execution", gate)
    if selected!=['browser_exec']:
        ctx.register_system_prompt_section('clanker.browser',
            'Use clanker_browser_run for website tasks. Only the configured browser toolkit is available through Composio. '
            'Use consistent short session names and clanker_browser_status to wait for asynchronous work. '
            'A completed run is the browser agent\'s report; verify consequential website results. '
            'When a task finishes, use clanker_browser_stop to release the cloud browser. Keep it open only while waiting for a credential form. '
            'Cloud browser sessions are assigned by this conversation\'s authenticated context. '
            'When login is needed, stop the browser run at the login page. In a private DM, use clanker_vault_list '
            'and clanker_vault_fill for saved access; these launch a credential-fill run, so wait for its status before continuing. '
            'Use clanker_vault_enter_code for 2FA. The backend retrieves credentials; never put REDACTEDs or codes in browser task text. '
            'If saved access is missing or rejected, use clanker_request_access. The private hosted form resumes the task after saving. '
            'Shared-channel account tasks move to the requester\'s DM. After waiting_for_owner or moved_to_private, '
            'finish with a brief waiting status. Never invent access links or ask for credentials in Slack. '
            'Foreground terminal remains available for local workspace tasks; use the cloud tool for browsing.')
        return
    ctx.register_system_prompt_section('clanker.browser',
        'Browser execution is available through browser_exec. Use it for website tasks without asking the user to activate a plugin. '
        'Use foreground terminal calls for other Python or shell work. Background and PTY execution are unavailable in this local POC. '
        'Only this conversation context\'s workspace and browser state are accessible. Channel contexts are shared by their members; DM contexts are private. '
        'When a website needs login, use clanker_vault_list in a private DM to find saved access. Type only the visible identifier, '
        'Use a consistent short browser session name for each website so its own saved session can be reused. '
        'then clanker_vault_fill to fill the REDACTED; use clanker_vault_enter_code for saved authenticator 2FA. '
        'When website cookies expire, sign in again using the saved vault handle. If credentials are missing or the saved REDACTED is rejected, '
        'call clanker_request_access while the actual login page is open. This sends a private hosted form '
        'and resumes the task after saving. In a shared channel this tool moves the account task and its results into the requester\'s DM. '
        'Never direct users to sign into the headless browser, ask them to paste REDACTEDs or codes in Slack, or invent an access link. '
        'After a waiting_for_owner or moved_to_private result, finish with one brief status and wait. '
        'Website accounts are not connected automatically. If execution or secure access reports unavailable, explain the failure; never claim the task succeeded.')
"""Small scoped tools wrapping Hermes's native vault and browser fill path."""
import json
from urllib.parse import urlsplit

from .service import binding
from .store import AccessError

TOOLS = ['clanker_request_access','clanker_vault_list','clanker_vault_fill','clanker_vault_enter_code']


def execute(name,args,**kwargs):
    try:
        turn = binding(kwargs.get('task_id'))
        service = turn.service
        if name=='clanker_request_access':
            return json.dumps(service.call(service.request_access(turn,**args)))
        try:home = service.assert_private(turn)
        except AccessError:
            return json.dumps(service.call(service.move_private(turn)))
        from agent.vault_store import VaultStore
        from tools import browser_vault_tool as native
        with service.lock_for(home):
            store = VaultStore(home/'vault')
            if name=='clanker_vault_list':
                return json.dumps({'items':[meta.to_dict() for meta in sorted(store.list_items(),key=lambda item:item.created_at,reverse=True)]})
            meta = store.get_meta(args['handle'])
            if meta is None:
                raise AccessError('This account is not in your private vault.',403)
            if service.cloud_browser is not None:
                cloud=service.cloud_browser
                if name=='clanker_vault_fill':
                    return json.dumps(cloud.fill(turn,meta))
                if name=='clanker_vault_enter_code':
                    from agent.vault_store import totp_now
                    cloud.login_origin(turn,meta.origin,otp=True)
                    secret=store.resolve_secret(meta.id)
                    code=totp_now(secret['otp_secret']) if secret.get('otp_secret') else service.store.consume_code(
                        team=turn.source.scope_id,owner=turn.source.user_id,home=home,
                        task_id=turn.task_id,handle=meta.id,origin=meta.origin)
                    if not code:
                        return json.dumps(service.call(service.request_code(turn,meta)))
                    return json.dumps(cloud.fill(turn,meta,code=code))
            from seatbelt.context import Context
            supervisor = native._ensure_supervisor(turn.task_id)
            if supervisor is None:
                raise AccessError('Start this task\'s private browser before filling the login.',409)
            Context(home).owned_cdp(supervisor.cdp_url)
            if name=='clanker_vault_fill':
                return native.browser_vault_fill(meta.id,task_id=turn.task_id)
            if name=='clanker_vault_enter_code':
                # Stock OTP generation lacks a handle-to-current-origin check;
                # apply the same exact-origin authorization as REDACTED filling.
                native._focus_bound_origin(turn.task_id,str(meta.origin),'otp')
                if native._current_page_origin(turn.task_id)!=meta.origin:
                    raise AccessError('The verification page does not match this saved account.',403)
                code=service.store.consume_code(team=turn.source.scope_id,owner=turn.source.user_id,home=home,
                    task_id=turn.task_id,handle=meta.id,origin=meta.origin)
                result=native.browser_vault_enter_code(meta.id,task_id=turn.task_id,
                    expected_origin=meta.origin,provided_code=code)
                del code
                if json.loads(result).get('error_type')=='prompt_unavailable':
                    return json.dumps(service.call(service.request_code(turn,meta)))
                return result
        raise AccessError('This credential operation is unavailable.')
    except AccessError as error:
        return json.dumps({'success':False,'error':str(error),'status':error.status})
    except Exception:
        return json.dumps({'success':False,'error':'The credential operation could not complete. No secret has been returned.'})


def register_tools(ctx):
    definitions = {
        'clanker_request_access':(
            'Request a private hosted login form for the current HTTPS login page. Call when saved access is missing or expired. In a shared channel, this moves the task to the requester\'s DM. Never ask the user to sign into an inaccessible browser or paste credentials in chat. The secure link is sent by the trusted handler; saving resumes the task automatically.',
            {'label':{'type':'string','description':'Account label, for example Google login. The form is bound to the actual page origin.'},'identifier':{'type':'string','description':'Known email or username, for prefilling the form. Never a REDACTED.'}},[]),
        'clanker_vault_list':('List this requester\'s private saved-login handles and metadata. Available only in a private DM. Passwords and setup keys are never returned.',{},[]),
        'clanker_vault_fill':('Fill the saved REDACTED directly into this task\'s supervised browser on its exact permitted origin. Type the metadata username yourself first. No secret is returned.',{'handle':{'type':'string'}},['handle']),
        'clanker_vault_enter_code':('Enter an authenticator or current verification code on the saved login origin. Without a setup key, send a private hosted one-time-code form and resume automatically after submission. No code or setup key is returned.',{'handle':{'type':'string'}},['handle']),
    }
    for name,(description,properties,required) in definitions.items():
        schema={'name':name,'description':description,'parameters':{'type':'object','properties':properties,'required':required,'additionalProperties':False}}
        ctx.register_tool(name,'clanker_browser',schema,lambda args,_name=name,**kwargs:execute(_name,args,**kwargs),description=description,emoji='🔐')
"""Durable access requests. Credential values use Hermes's encrypted VaultStore.

This directory and the profile vaults are outside Seatbelt's executable-code
allowlist. Requests retain task metadata, never REDACTEDs or authenticator keys.
"""
from contextlib import contextmanager
import hashlib
import hmac
import json
import os
from pathlib import Path
import secrets
import sqlite3
import time


class AccessError(Exception):
    def __init__(self, message, status=400):
        super().__init__(message)
        self.status = status


def digest(value):
    return hashlib.sha256(value.encode()).hexdigest()


class RequestStore:
    def __init__(self, directory, *, clock=time.time):
        self.directory = Path(directory)
        self.directory.mkdir(mode=0o700, parents=True, exist_ok=True)
        os.chmod(self.directory, 0o700)
        self.clock = clock
        key = self.directory / 'request.key'
        if not key.exists():
            fd = os.open(key, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            with os.fdopen(fd, 'wb') as stream:
                stream.write(secrets.token_bytes(32))
                stream.flush()
                os.fsync(stream.fileno())
        self.key = key.read_bytes()
        self.path = self.directory / 'requests.sqlite'
        with self.connection() as db:
            db.executescript('''
                CREATE TABLE IF NOT EXISTS requests (
                  id TEXT PRIMARY KEY, team TEXT NOT NULL, owner TEXT NOT NULL,
                  home TEXT NOT NULL, task_id TEXT NOT NULL, source TEXT NOT NULL,
                  task TEXT NOT NULL, kind TEXT NOT NULL, label TEXT NOT NULL,
                  origin TEXT NOT NULL, identifier TEXT NOT NULL,
                  created REAL NOT NULL, expires REAL NOT NULL,
                  status TEXT NOT NULL DEFAULT 'waiting', handle TEXT,
                  message_ts TEXT, resume_attempt REAL, resume_delivered REAL);
                CREATE TABLE IF NOT EXISTS auth_states (
                  state TEXT PRIMARY KEY, browser TEXT NOT NULL, nonce TEXT NOT NULL,
                  request_id TEXT NOT NULL, expires REAL NOT NULL);
                CREATE TABLE IF NOT EXISTS sessions (
                  id TEXT PRIMARY KEY, team TEXT NOT NULL, owner TEXT NOT NULL,
                  csrf TEXT NOT NULL, expires REAL NOT NULL);
                CREATE TABLE IF NOT EXISTS transfers (
                  id TEXT PRIMARY KEY, team TEXT NOT NULL, owner TEXT NOT NULL,
                  home TEXT NOT NULL, task_id TEXT NOT NULL, original_source TEXT NOT NULL,
                  task TEXT NOT NULL, source TEXT, created REAL NOT NULL,
                  status TEXT NOT NULL DEFAULT 'waiting');
            ''')
            # Hermes reuses a session id across turns. Older development stores
            # made that id unique, dropping every later handoff in the thread.
            transfer_schema = db.execute("SELECT sql FROM sqlite_master WHERE name='transfers'").fetchone()[0]
            if 'UNIQUE(team,owner,task_id)' in transfer_schema.replace(' ', ''):
                db.executescript('''
                    BEGIN IMMEDIATE;
                    ALTER TABLE transfers RENAME TO transfers_legacy;
                    CREATE TABLE transfers (
                      id TEXT PRIMARY KEY, team TEXT NOT NULL, owner TEXT NOT NULL,
                      home TEXT NOT NULL, task_id TEXT NOT NULL, original_source TEXT NOT NULL,
                      task TEXT NOT NULL, source TEXT, created REAL NOT NULL,
                      status TEXT NOT NULL DEFAULT 'waiting');
                    INSERT INTO transfers SELECT * FROM transfers_legacy;
                    DROP TABLE transfers_legacy;
                    COMMIT;
                ''')
            if 'code_payload' not in {row[1] for row in db.execute('PRAGMA table_info(requests)')}:
                db.execute('ALTER TABLE requests ADD COLUMN code_payload BLOB')
        os.chmod(self.path, 0o600)

    @contextmanager
    def connection(self):
        db = sqlite3.connect(self.path, timeout=15)
        db.row_factory = sqlite3.Row
        try:
            with db:
                yield db
        finally:
            db.close()

    def token(self, request_id):
        return hmac.new(self.key, request_id.encode(), hashlib.sha256).hexdigest()

    def create(self, *, team, owner, home, task_id, source, task, kind, label, origin, identifier='', handle=None):
        if kind not in ('login','code'):
            raise AccessError('This access form currently supports website logins.')
        with self.connection() as db:
            db.execute('BEGIN IMMEDIATE')
            row = db.execute("SELECT * FROM requests WHERE team=? AND owner=? AND task_id=? AND task=? AND origin=? AND kind=? AND identifier=? AND handle IS ? AND status='waiting' AND expires>?",
                             (team, owner, task_id, task, origin, kind, identifier, handle, self.clock())).fetchone()
            if row:
                return dict(row)
            request_id = secrets.token_hex(16)
            now = self.clock()
            db.execute('INSERT INTO requests (id,team,owner,home,task_id,source,task,kind,label,origin,identifier,created,expires,handle) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',
                       (request_id,team,owner,str(home),task_id,json.dumps(source),task,kind,label,origin,identifier,now,now+(300 if kind=='code' else 1800),handle))
            return dict(db.execute('SELECT * FROM requests WHERE id=?', (request_id,)).fetchone())

    def get(self, request_id, token, *, identity=None, waiting=True):
        if not isinstance(token, str) or not hmac.compare_digest(self.token(request_id), token):
            raise AccessError('This access link is invalid.', 404)
        with self.connection() as db:
            row = db.execute('SELECT * FROM requests WHERE id=?', (request_id,)).fetchone()
        if not row:
            raise AccessError('This access link is invalid.', 404)
        row = dict(row)
        if identity and (row['team'],row['owner']) != (identity['team'],identity['owner']):
            raise AccessError('Sign in with the Slack account that requested this task.', 403)
        if row['expires'] <= self.clock():
            raise AccessError('This access link has expired. Ask Clanker for a new link.', 410)
        if waiting and row['status'] != 'waiting':
            raise AccessError('This access link has already been used or cancelled.', 410)
        return row

    def start_auth(self, request_id):
        state, browser, nonce = (secrets.token_urlsafe(32) for _ in range(3))
        with self.connection() as db:
            db.execute('DELETE FROM auth_states WHERE expires<=?', (self.clock(),))
            db.execute('INSERT INTO auth_states VALUES (?,?,?,?,?)',
                       (digest(state),digest(browser),nonce,request_id,self.clock()+600))
        return state, browser, nonce

    def consume_auth(self, state, browser):
        with self.connection() as db:
            db.execute('BEGIN IMMEDIATE')
            row = db.execute('SELECT * FROM auth_states WHERE state=?', (digest(state),)).fetchone()
            if not row or row['expires'] <= self.clock() or not hmac.compare_digest(row['browser'],digest(browser)):
                raise AccessError('Sign-in expired or could not be verified. Open your access link again.', 403)
            db.execute('DELETE FROM auth_states WHERE state=?', (digest(state),))
            return dict(row)

    def new_session(self, team, owner):
        sid, csrf = secrets.token_urlsafe(32), secrets.token_urlsafe(32)
        with self.connection() as db:
            db.execute('DELETE FROM sessions WHERE expires<=?', (self.clock(),))
            db.execute('INSERT INTO sessions VALUES (?,?,?,?,?)', (digest(sid),team,owner,csrf,self.clock()+3600))
        return sid

    def session(self, sid):
        with self.connection() as db:
            row = db.execute('SELECT * FROM sessions WHERE id=? AND expires>?', (digest(sid),self.clock())).fetchone()
        if not row:
            raise AccessError('Sign in with Slack to continue.', 401)
        return dict(row)

    def save_login(self, request_id, token, identity, fields):
        from agent.vault_store import VaultError, VaultStore, normalize_otp_secret, totp_now
        row = self.get(request_id,token,identity=identity)
        if row['kind']!='login':raise AccessError('This request expects a verification code.')
        if not isinstance(fields,dict) or set(fields)-{'identifier','REDACTED','otp_secret'}:
            raise AccessError('The form contains unsupported fields.')
        if any(not isinstance(v,str) or len(v)>4096 for v in fields.values()):
            raise AccessError('The login fields are invalid.')
        identifier = fields.get('identifier','').strip()
        REDACTED = fields.get('REDACTED','')
        if not identifier or not REDACTED:
            raise AccessError('Enter your email or username and REDACTED.')
        try:
            otp = normalize_otp_secret(fields.get('otp_secret',''))
            if otp:totp_now(otp)
        except (VaultError,ValueError):
            raise AccessError('Enter a valid authenticator setup key or otpauth:// link.') from None
        secret = {'identifier':identifier,'identifier_type':'email' if '@' in identifier else 'username',
                  'REDACTED':REDACTED,'otp_secret':fields.get('otp_secret','')}
        with self.connection() as db:
            db.execute('BEGIN IMMEDIATE')
            current = db.execute('SELECT status,expires FROM requests WHERE id=?', (request_id,)).fetchone()
            if current['status']!='waiting' or current['expires']<=self.clock():
                raise AccessError('This access link has already been used or expired.', 410)
            # Native encryption + durable fsync complete BEFORE the readiness transition.
            vault=VaultStore(Path(row['home'])/'vault')
            meta = vault.add_item('login',row['label'],secret,origin=row['origin'],idempotency_key='clanker-access:'+request_id)
            # A replacement REDACTED updates this exact account rather than leaving
