"""Durable access requests. Credential values use Hermes's encrypted VaultStore.

This directory and the profile vaults are outside Seatbelt's executable-code
allowlist. Requests retain task metadata, never REDACTEDs or authenticator keys.
"""
from contextlib import contextmanager
import hashlib
import hmac
import json
import os
from pathlib import Path
import secrets
import sqlite3
import time


class AccessError(Exception):
    def __init__(self, message, status=400):
        super().__init__(message)
        self.status = status


def digest(value):
    return hashlib.sha256(value.encode()).hexdigest()


class RequestStore:
    def __init__(self, directory, *, clock=time.time):
        self.directory = Path(directory)
        self.directory.mkdir(mode=0o700, parents=True, exist_ok=True)
        os.chmod(self.directory, 0o700)
        self.clock = clock
        key = self.directory / 'request.key'
        if not key.exists():
            fd = os.open(key, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            with os.fdopen(fd, 'wb') as stream:
                stream.write(secrets.token_bytes(32))
                stream.flush()
                os.fsync(stream.fileno())
        self.key = key.read_bytes()
        self.path = self.directory / 'requests.sqlite'
        with self.connection() as db:
            db.executescript('''
                CREATE TABLE IF NOT EXISTS requests (
                  id TEXT PRIMARY KEY, team TEXT NOT NULL, owner TEXT NOT NULL,
                  home TEXT NOT NULL, task_id TEXT NOT NULL, source TEXT NOT NULL,
                  task TEXT NOT NULL, kind TEXT NOT NULL, label TEXT NOT NULL,
                  origin TEXT NOT NULL, identifier TEXT NOT NULL,
                  created REAL NOT NULL, expires REAL NOT NULL,
                  status TEXT NOT NULL DEFAULT 'waiting', handle TEXT,
                  message_ts TEXT, resume_attempt REAL, resume_delivered REAL);
                CREATE TABLE IF NOT EXISTS auth_states (
                  state TEXT PRIMARY KEY, browser TEXT NOT NULL, nonce TEXT NOT NULL,
                  request_id TEXT NOT NULL, expires REAL NOT NULL);
                CREATE TABLE IF NOT EXISTS sessions (
                  id TEXT PRIMARY KEY, team TEXT NOT NULL, owner TEXT NOT NULL,
                  csrf TEXT NOT NULL, expires REAL NOT NULL);
                CREATE TABLE IF NOT EXISTS transfers (
                  id TEXT PRIMARY KEY, team TEXT NOT NULL, owner TEXT NOT NULL,
                  home TEXT NOT NULL, task_id TEXT NOT NULL, original_source TEXT NOT NULL,
                  task TEXT NOT NULL, source TEXT, created REAL NOT NULL,
                  status TEXT NOT NULL DEFAULT 'waiting');
            ''')
            # Hermes reuses a session id across turns. Older development stores
            # made that id unique, dropping every later handoff in the thread.
            transfer_schema = db.execute("SELECT sql FROM sqlite_master WHERE name='transfers'").fetchone()[0]
            if 'UNIQUE(team,owner,task_id)' in transfer_schema.replace(' ', ''):
                db.executescript('''
                    BEGIN IMMEDIATE;
                    ALTER TABLE transfers RENAME TO transfers_legacy;
                    CREATE TABLE transfers (
                      id TEXT PRIMARY KEY, team TEXT NOT NULL, owner TEXT NOT NULL,
                      home TEXT NOT NULL, task_id TEXT NOT NULL, original_source TEXT NOT NULL,
                      task TEXT NOT NULL, source TEXT, created REAL NOT NULL,
                      status TEXT NOT NULL DEFAULT 'waiting');
                    INSERT INTO transfers SELECT * FROM transfers_legacy;
                    DROP TABLE transfers_legacy;
                    COMMIT;
                ''')
            if 'code_payload' not in {row[1] for row in db.execute('PRAGMA table_info(requests)')}:
                db.execute('ALTER TABLE requests ADD COLUMN code_payload BLOB')
        os.chmod(self.path, 0o600)

    @contextmanager
    def connection(self):
        db = sqlite3.connect(self.path, timeout=15)
        db.row_factory = sqlite3.Row
        try:
            with db:
                yield db
        finally:
            db.close()

    def token(self, request_id):
        return hmac.new(self.key, request_id.encode(), hashlib.sha256).hexdigest()

    def create(self, *, team, owner, home, task_id, source, task, kind, label, origin, identifier='', handle=None):
        if kind not in ('login','code'):
            raise AccessError('This access form currently supports website logins.')
        with self.connection() as db:
            db.execute('BEGIN IMMEDIATE')
            row = db.execute("SELECT * FROM requests WHERE team=? AND owner=? AND task_id=? AND task=? AND origin=? AND kind=? AND identifier=? AND handle IS ? AND status='waiting' AND expires>?",
                             (team, owner, task_id, task, origin, kind, identifier, handle, self.clock())).fetchone()
            if row:
                return dict(row)
            request_id = secrets.token_hex(16)
            now = self.clock()
            db.execute('INSERT INTO requests (id,team,owner,home,task_id,source,task,kind,label,origin,identifier,created,expires,handle) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',
                       (request_id,team,owner,str(home),task_id,json.dumps(source),task,kind,label,origin,identifier,now,now+(300 if kind=='code' else 1800),handle))
            return dict(db.execute('SELECT * FROM requests WHERE id=?', (request_id,)).fetchone())

    def get(self, request_id, token, *, identity=None, waiting=True):
        if not isinstance(token, str) or not hmac.compare_digest(self.token(request_id), token):
            raise AccessError('This access link is invalid.', 404)
        with self.connection() as db:
            row = db.execute('SELECT * FROM requests WHERE id=?', (request_id,)).fetchone()
        if not row:
            raise AccessError('This access link is invalid.', 404)
        row = dict(row)
        if identity and (row['team'],row['owner']) != (identity['team'],identity['owner']):
            raise AccessError('Sign in with the Slack account that requested this task.', 403)
        if row['expires'] <= self.clock():
            raise AccessError('This access link has expired. Ask Clanker for a new link.', 410)
        if waiting and row['status'] != 'waiting':
            raise AccessError('This access link has already been used or cancelled.', 410)
        return row

    def start_auth(self, request_id):
        state, browser, nonce = (secrets.token_urlsafe(32) for _ in range(3))
        with self.connection() as db:
            db.execute('DELETE FROM auth_states WHERE expires<=?', (self.clock(),))
            db.execute('INSERT INTO auth_states VALUES (?,?,?,?,?)',
                       (digest(state),digest(browser),nonce,request_id,self.clock()+600))
        return state, browser, nonce

    def consume_auth(self, state, browser):
        with self.connection() as db:
            db.execute('BEGIN IMMEDIATE')
            row = db.execute('SELECT * FROM auth_states WHERE state=?', (digest(state),)).fetchone()
            if not row or row['expires'] <= self.clock() or not hmac.compare_digest(row['browser'],digest(browser)):
                raise AccessError('Sign-in expired or could not be verified. Open your access link again.', 403)
            db.execute('DELETE FROM auth_states WHERE state=?', (digest(state),))
            return dict(row)

    def new_session(self, team, owner):
        sid, csrf = secrets.token_urlsafe(32), secrets.token_urlsafe(32)
        with self.connection() as db:
            db.execute('DELETE FROM sessions WHERE expires<=?', (self.clock(),))
            db.execute('INSERT INTO sessions VALUES (?,?,?,?,?)', (digest(sid),team,owner,csrf,self.clock()+3600))
        return sid

    def session(self, sid):
        with self.connection() as db:
            row = db.execute('SELECT * FROM sessions WHERE id=? AND expires>?', (digest(sid),self.clock())).fetchone()
        if not row:
            raise AccessError('Sign in with Slack to continue.', 401)
        return dict(row)

    def save_login(self, request_id, token, identity, fields):
        from agent.vault_store import VaultError, VaultStore, normalize_otp_secret, totp_now
        row = self.get(request_id,token,identity=identity)
        if row['kind']!='login':raise AccessError('This request expects a verification code.')
        if not isinstance(fields,dict) or set(fields)-{'identifier','REDACTED','otp_secret'}:
            raise AccessError('The form contains unsupported fields.')
        if any(not isinstance(v,str) or len(v)>4096 for v in fields.values()):
            raise AccessError('The login fields are invalid.')
        identifier = fields.get('identifier','').strip()
        REDACTED = fields.get('REDACTED','')
        if not identifier or not REDACTED:
            raise AccessError('Enter your email or username and REDACTED.')
        try:
            otp = normalize_otp_secret(fields.get('otp_secret',''))
            if otp:totp_now(otp)
        except (VaultError,ValueError):
            raise AccessError('Enter a valid authenticator setup key or otpauth:// link.') from None
        secret = {'identifier':identifier,'identifier_type':'email' if '@' in identifier else 'username',
                  'REDACTED':REDACTED,'otp_secret':fields.get('otp_secret','')}
        with self.connection() as db:
            db.execute('BEGIN IMMEDIATE')
            current = db.execute('SELECT status,expires FROM requests WHERE id=?', (request_id,)).fetchone()
            if current['status']!='waiting' or current['expires']<=self.clock():
                raise AccessError('This access link has already been used or expired.', 410)
            # Native encryption + durable fsync complete BEFORE the readiness transition.
            vault=VaultStore(Path(row['home'])/'vault')
            meta = vault.add_item('login',row['label'],secret,origin=row['origin'],idempotency_key='clanker-access:'+request_id)
            # A replacement REDACTED updates this exact account rather than leaving
            # the next task to select a stale duplicate. Other accounts are retained.
            for old in vault.list_items():
                if old.id!=meta.id and old.kind=='login' and old.origin==meta.origin and old.identifier==meta.identifier:
                    vault.remove_item(old.id)
            db.execute("UPDATE requests SET status='saved',handle=? WHERE id=?", (meta.id,request_id))
        return meta

    def pending_resumes(self):
        with self.connection() as db:
            return [dict(row) for row in db.execute("SELECT * FROM requests WHERE status='saved' ORDER BY created")]

    def pending_links(self):
        with self.connection() as db:
            db.execute('UPDATE requests SET code_payload=NULL WHERE kind=\'code\' AND expires<=?',(self.clock(),))
            return [dict(row) for row in db.execute("SELECT * FROM requests WHERE status='waiting' AND message_ts IS NULL AND expires>?",(self.clock(),))]

    def recover_saves(self):
        """Adopt a native vault save that fsynced just before the request transaction crashed."""
        from agent.vault_store import VaultStore
        with self.connection() as db:
            db.execute('BEGIN IMMEDIATE')
            for row in db.execute("SELECT * FROM requests WHERE status='waiting' AND kind='login'").fetchall():
                store = VaultStore(Path(row['home'])/'vault')
                meta = store.get_meta(store.id_for_key('clanker-access:'+row['id']))
                if meta and meta.origin==row['origin'] and meta.label==row['label']:
                    db.execute("UPDATE requests SET status='saved',handle=? WHERE id=?",(meta.id,row['id']))

    def code_crypto(self):
        import base64
        from cryptography.fernet import Fernet
        return Fernet(base64.urlsafe_b64encode(hmac.new(self.key,b'one-time-code',hashlib.sha256).digest()))

    def save_code(self, request_id, token, identity, fields):
        import re
        row=self.get(request_id,token,identity=identity)
        if row['kind']!='code' or not isinstance(fields,dict) or set(fields)!={'code'}:
            raise AccessError('This request expects only the current verification code.')
        code=fields['code']
        if not isinstance(code,str) or not re.fullmatch(r'[A-Za-z0-9 -]{4,32}',code):
            raise AccessError('Enter the code shown by your authenticator, phone, or email.')
        code=code.replace(' ','').replace('-','')
        with self.connection() as db:
            db.execute('BEGIN IMMEDIATE')
            current=db.execute('SELECT status,expires FROM requests WHERE id=?',(request_id,)).fetchone()
            if current['status']!='waiting' or current['expires']<=self.clock():raise AccessError('This code link has expired or already been used.',410)
            db.execute("UPDATE requests SET status='saved',code_payload=?,expires=? WHERE id=?",
                       (self.code_crypto().encrypt(code.encode()),min(current['expires'],self.clock()+90),request_id))
        return row['label']

    def consume_code(self, *, team, owner, home, handle, origin, task_id):
        with self.connection() as db:
            db.execute('BEGIN IMMEDIATE')
            row=db.execute("SELECT * FROM requests WHERE team=? AND owner=? AND home=? AND task_id=? AND handle=? AND origin=? AND kind='code' AND status IN ('saved','resumed') AND expires>? AND code_payload IS NOT NULL ORDER BY created DESC LIMIT 1",
                           (team,owner,str(home),task_id,handle,origin,self.clock())).fetchone()
            if not row:return None
            code=self.code_crypto().decrypt(row['code_payload']).decode()
            db.execute('UPDATE requests SET code_payload=NULL WHERE id=?',(row['id'],))
            return code

    def mark_resumed(self, request_id):
        with self.connection() as db:
            db.execute("UPDATE requests SET status='resumed',resume_delivered=? WHERE id=? AND status='saved'", (self.clock(),request_id))

    def transfer(self, *, team, owner, home, task_id, source, task):
        with self.connection() as db:
            db.execute('BEGIN IMMEDIATE')
            candidates = db.execute("SELECT * FROM transfers WHERE team=? AND owner=? AND task_id=? AND task=? AND status IN ('waiting','saved')",
                                    (team,owner,task_id,task)).fetchall()
            for row in candidates:
                if json.loads(row['original_source'])==source:
                    return dict(row)
            transfer_id = secrets.token_hex(16)
            db.execute('INSERT INTO transfers (id,team,owner,home,task_id,original_source,task,created) VALUES (?,?,?,?,?,?,?,?)',
                       (transfer_id,team,owner,str(home),task_id,json.dumps(source),task,self.clock()))
            return dict(db.execute('SELECT * FROM transfers WHERE id=?',(transfer_id,)).fetchone())

    def pending_transfers(self):
        with self.connection() as db:
            return [dict(row) for row in db.execute("SELECT * FROM transfers WHERE status IN ('waiting','saved') ORDER BY created")]

    def set_transfer_source(self, request_id, source):
        with self.connection() as db:
            db.execute("UPDATE transfers SET source=?,status='saved' WHERE id=? AND status='waiting'",(json.dumps(source),request_id))

    def mark_transfer_resumed(self, request_id):
        with self.connection() as db:
            db.execute("UPDATE transfers SET status='resumed' WHERE id=? AND status='saved'",(request_id,))

    def is_pending(self, request_id, *, transfer=False):
        table='transfers' if transfer else 'requests'
        with self.connection() as db:
            row=db.execute(f'SELECT status FROM {table} WHERE id=?',(request_id,)).fetchone()
        return bool(row and row['status'] in ('waiting','saved'))

    def cancel_owner(self, team, owner):
        """Disconnect cancels outstanding account work before removing its credentials."""
        with self.connection() as db:
            for table in ('requests','transfers'):
                db.execute(f"UPDATE {table} SET status='cancelled' WHERE team=? AND owner=? AND status IN ('waiting','saved')",(team,owner))
            db.execute('UPDATE requests SET code_payload=NULL WHERE team=? AND owner=?',(team,owner))

    def cancel(self, *, team, owner, source):
        count=0
        with self.connection() as db:
            for table in ('requests','transfers'):
                rows=db.execute(f"SELECT * FROM {table} WHERE team=? AND owner=? AND status IN ('waiting','saved')",(team,owner)).fetchall()
                for row in rows:
                    candidates=[json.loads(row['source'])] if row['source'] else []
                    if table=='transfers':candidates.append(json.loads(row['original_source']))
                    if any(item.get('chat_id')==source['chat_id'] and
                           (not source.get('thread_id') or item.get('thread_id')==source['thread_id']) for item in candidates):
                        db.execute(f"UPDATE {table} SET status='cancelled' WHERE id=?",(row['id'],));count+=1
                        if table=='requests':db.execute('UPDATE requests SET code_payload=NULL WHERE id=?',(row['id'],))
        return count
"""Authenticated Slack turns -> private links -> durable save -> private resume.

The model never selects an owner, profile path, or link token. Only the live
gateway turn may bind a tool call to the already authenticated Slack source.
"""
import asyncio
from dataclasses import dataclass
import json
from pathlib import Path
import threading
from urllib.parse import urlencode, urlsplit

from .store import AccessError, RequestStore

_lock = threading.RLock()


@dataclass
class Binding:
    service: object
    source: object
    task_id: str
    message: str
    home: Path


def binding(task_id):
    from hermes_constants import get_hermes_home
    from agent.gateway_context import current_gateway_turn
    from gateway.slack_workspace import workspace_policy
    current=current_gateway_turn()
    if current and current.task_id==str(task_id) and current.home==str(get_hermes_home()):
        policy=workspace_policy(current.runner,current.source)
        service=getattr(policy,'vault_service',None)
        if service:
            result=Binding(service,current.source,current.task_id,current.message,Path(current.home))
            service.validate_member(result.source.scope_id,result.source.user_id)
            if policy.authorize_source(result.source):return result
        raise AccessError('Secure access is unavailable in this session. The hosted vault must be connected by the operator.',503)
    raise AccessError('Secure access is unavailable in this session. The hosted vault must be connected by the operator.',503)


async def on_gateway_control(command, source, runner):
    if command not in ('stop','new','reset'):return None
    from gateway.slack_workspace import workspace_policy
    policy=workspace_policy(runner,source)
    service=getattr(policy,'vault_service',None)
    if service and policy.authorize_source(source):
        count=await asyncio.to_thread(service.store.cancel,team=source.scope_id,owner=source.user_id,source=source.to_dict())
        if service.cloud_browser is not None:
            home=policy.home if source.profile=='default' else policy.home/'profiles'/source.profile
            turn=Binding(service,source,'control','',home.resolve(strict=True))
            await asyncio.to_thread(service.cloud_browser.stop,turn)
        return {'cancelled_pending':count}


class VaultService:
    def __init__(self, policy, config):
        self.policy, self.config = policy, config
        self.store = RequestStore(policy.home/'.clanker-vault')
        self.loop = None
        self.fill_locks = {}
        self.resume_tasks = {}
        from cloud_browser.service import configured
        self.cloud_browser = configured(self)

    def validate_member(self, team, owner):
        member = self.policy.state['members'].get(owner,{})
        if team!=self.policy.team or member.get('status')!='ready':
            raise AccessError('This Slack account is not authorized for Clanker.',403)
        return member

    def private_home(self, team, owner):
        member = self.validate_member(team,owner)
        profile = member['profile']
        home = self.policy.home if profile=='default' else self.policy.home/'profiles'/profile
        home = home.resolve(strict=True)
        if home!=self.policy.home.resolve() and not home.is_relative_to((self.policy.home/'profiles').resolve()):
            raise AccessError('The private account context is unavailable.',403)
        return home

    def assert_private(self, turn):
        home = self.private_home(turn.source.scope_id,turn.source.user_id)
        conversation = self.policy.state['conversations'].get(turn.source.chat_id,{})
        if conversation.get('kind')!='dm' or home!=turn.home.resolve():
            raise AccessError('Private accounts are available only in your DM with Clanker.',403)
        return home

    def call(self, coroutine):
        if self.loop is None or not self.loop.is_running():
            coroutine.close()
            raise AccessError('The hosted credential service is unavailable.',503)
        future = asyncio.run_coroutine_threadsafe(coroutine,self.loop)
        try:
            return future.result(timeout=30)
        except TimeoutError:
            future.cancel()
            raise AccessError('The access request is still pending. Please retry shortly.',503) from None

    def lock_for(self, home):
        with _lock:
            return self.fill_locks.setdefault(str(home),threading.RLock())

    async def move_private(self, turn):
        home=self.private_home(turn.source.scope_id,turn.source.user_id)
        row=self.store.transfer(team=turn.source.scope_id,owner=turn.source.user_id,home=home,
            task_id=turn.task_id,source=turn.source.to_dict(),task=turn.message)
        await self.deliver_transfer(row)
        await self.drain()
        return {'status':'moved_to_private','private_results':True}

    async def deliver_transfer(self, row):
        from gateway.session import SessionSource
        from gateway.config import Platform
        if row.get('source') or row['status']!='waiting':return
        member = self.validate_member(row['team'],row['owner'])
        dm = member['dm_id']
        # A channel request authorizes the requester's account operation, never
        # exposing their login/session or observations to that channel audience.
        message_id = 'clanker-private-'+row['id']
        from uuid import uuid5, NAMESPACE_URL
        client_id = str(uuid5(NAMESPACE_URL,message_id))
        history = await self.policy.client().conversations_history(channel=dm,limit=100)
        existing = next((m for m in history.get('messages',[]) if m.get('client_msg_id')==client_id),None)
        delivered = existing or await self.policy.client().chat_postMessage(channel=dm,
            text="I'll handle your account access and results privately here.",client_msg_id=client_id)
        original=json.loads(row['original_source'])
        source = SessionSource(platform=Platform.SLACK,chat_id=dm,chat_type='dm',user_id=row['owner'],
                               user_name=original.get('user_name'),thread_id=delivered['ts'],scope_id=row['team'],
                               profile=member['profile'])
        self.store.set_transfer_source(row['id'],source.to_dict())

    async def request_access(self, turn, *, label='', identifier=''):
        from tools.browser_vault_tool import _current_page_origin, _ensure_supervisor
        try:
            home = self.assert_private(turn)
        except AccessError:
            return await self.move_private(turn)
        # Origin comes from the live browser, never the model's site string.
        if self.cloud_browser is not None:
            origin = await asyncio.to_thread(self.cloud_browser.login_origin,turn)
        else:
            from gateway.run import _profile_runtime_scope
            def login_origin():
                from seatbelt.context import Context
                supervisor=_ensure_supervisor(turn.task_id)
                if supervisor is None:raise AccessError('Open the account login page before requesting access.',409)
                Context(home).owned_cdp(supervisor.cdp_url)
                # Google and other providers show an identifier-only first step.
                probe="Boolean(document.querySelector('input[type=REDACTED],input[type=email],input[autocomplete=username],input[name=login],input[name=username],input[name=identifier],input#identifierId'))"
                focused=supervisor.focus_page('',accept=probe)
                if not focused.get('ok'):raise AccessError('Open the account login form before requesting access.',409)
                return _current_page_origin(turn.task_id)
            with _profile_runtime_scope(home):
                origin = await asyncio.to_thread(login_origin)
        if not origin or urlsplit(origin).scheme!='https':
            raise AccessError('Open the account\'s HTTPS login page before requesting credentials.')
        host = urlsplit(origin).hostname
        # The hostname is authoritative; an optional account label is display-only.
        label = (label.strip()[:120]+' · '+host) if label.strip() else host+' login'
        request = self.store.create(team=turn.source.scope_id,owner=turn.source.user_id,home=home,
                                    task_id=turn.task_id,source=turn.source.to_dict(),task=turn.message,
                                    kind='login',label=label,origin=origin,identifier=identifier.strip()[:320])
        await self.deliver_link(request)
        return {'status':'waiting_for_owner','request_id':request['id'],'origin':origin,
                'next':'The private secure link has been sent. End this turn with a brief waiting update. Saving access resumes this task automatically.'}

    async def deliver_link(self, row):
        if row.get('message_ts'):
            return
        member = self.validate_member(row['team'],row['owner'])
        from uuid import uuid5, NAMESPACE_URL
        message_id = str(uuid5(NAMESPACE_URL,'clanker-access:'+row['id']))
        history = await self.policy.client().conversations_history(channel=member['dm_id'],limit=100)
        posted = next((m for m in history.get('messages',[]) if m.get('client_msg_id')==message_id),None)
        if not posted:
            url = self.config['public_url'].rstrip('/')+'/vault/fill#'+urlencode({'r':row['id'],'token':self.store.token(row['id'])})
            source = json.loads(row['source'])
            is_code=row['kind']=='code'
            instruction=("Enter your current verification code securely. I'll continue after you submit it." if is_code else
                         "Add your login securely. I'll continue after you save it.")
            posted = await self.policy.client().chat_postMessage(channel=member['dm_id'],
                thread_ts=source.get('thread_id') or None,client_msg_id=message_id,unfurl_links=False,unfurl_media=False,
                text=urlsplit(row['origin']).hostname+': '+instruction,
                blocks=[{'type':'section','text':{'type':'plain_text','text':row['label']+'\n'+instruction}},
                        {'type':'actions','elements':[{'type':'button','text':{'type':'plain_text','text':'Enter verification code' if is_code else 'Add login to vault'},'url':url,'action_id':'clanker_vault_link'}]}])
        with self.store.connection() as db:
            db.execute('UPDATE requests SET message_ts=? WHERE id=?', (posted['ts'],row['id']))

    async def request_code(self, turn, meta):
        home=self.assert_private(turn)
        row=self.store.create(team=turn.source.scope_id,owner=turn.source.user_id,home=home,task_id=turn.task_id,
            source=turn.source.to_dict(),task=turn.message,kind='code',label=meta.label+' verification',
            origin=meta.origin,identifier=meta.identifier or '',handle=meta.id)
        await self.deliver_link(row)
        return {'status':'waiting_for_owner','request_id':row['id'],
                'next':'A private secure code form has been sent. End this turn. Submitting the code resumes the task automatically.'}

    def delivery_owned(self, key, event_id):
        """A native final-response obligation owns delivery across the outbox crash gap."""
        from gateway.delivery_ledger import _db_path, compute_obligation_id
        import sqlite3
        path=_db_path()
        if not path.exists():return False
        with sqlite3.connect('file:'+str(path)+'?mode=ro',uri=True) as db:
            if not db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='delivery_obligations'").fetchone():return False
            for oid,content in db.execute('SELECT obligation_id,content FROM delivery_obligations WHERE session_key=?',(key,)):
                if oid==compute_obligation_id(key,event_id,content):return True
        return False

    async def resume(self, row, *, transfer=False):
        from gateway.session import SessionSource
        from gateway.platforms.event import MessageEvent
        member = self.validate_member(row['team'],row['owner'])
        source = SessionSource.from_dict(json.loads(row['source']))
        if source.chat_id!=member['dm_id'] or source.profile!=member['profile'] or self.private_home(row['team'],row['owner'])!=Path(row['home']):
            raise AccessError('The original private task is no longer authorized.',403)
        if not self.store.is_pending(row['id'],transfer=transfer):return
        prefix=("Continue the requester's private account task. Keep account observations and results in this DM." if transfer else
                f"{'Verification code submitted; use clanker_vault_enter_code' if row['kind']=='code' else 'Access saved'} for {row['label']} ({row['origin']}). Credential handle: {row['handle']}. Continue the original task below, verifying the result before reporting completion.")
        event_id=('clanker-private-resume-' if transfer else 'clanker-access-resume-')+row['id']
        event = MessageEvent(source=source,user_id=source.user_id,user_name=source.user_name,
            text=prefix+'\n\nOriginal request: '+row['task'],message_id=event_id,
            allow_gateway_control=False,metadata={'clanker_private_resume' if transfer else 'clanker_access_resume':row['id']})
        # Use the native gateway turn/delivery path and await its completion. The
        # saved record stays retryable across shutdown, with no secret in events.
        adapter = self.policy.adapter
        adapter._canonicalize(source)
        key = adapter._event_session_key(event)
        if key in adapter._active_sessions:
            return
        finish=self.store.mark_transfer_resumed if transfer else self.store.mark_resumed
        if await asyncio.to_thread(self.delivery_owned,key,event_id):
            finish(row['id']);return
        await adapter.handle_message(event)
        if not getattr(event,'_gateway_accepted',False):
            return
        task = adapter._session_tasks.get(key)
        if task is None:
            return
        await asyncio.shield(task)
        finish(row['id'])

    async def drain(self):
        await asyncio.to_thread(self.store.recover_saves)
        async def dispatch(row,transfer):
            try:
                if transfer:
                    await self.deliver_transfer(row)
                    row=next((item for item in self.store.pending_transfers() if item['id']==row['id']),None)
                    if row is None:return
                if not transfer and row['status']=='waiting':await self.deliver_link(row)
                else:await self.resume(row,transfer=transfer)
            except Exception:
                # No raw exceptions or links in logs. Retry on the next pass.
                pass
        for transfer,rows in ((False,self.store.pending_links()+self.store.pending_resumes()),(True,self.store.pending_transfers())):
            for row in rows:
                row_id=row['id']
                if row_id in self.resume_tasks:continue
                # Freeze the cleanup key per task; membership polling stays responsive.
                async def run(row=row,transfer=transfer,row_id=row_id):
                    try:await dispatch(row,transfer)
                    finally:self.resume_tasks.pop(row_id,None)
                self.resume_tasks[row_id]=asyncio.create_task(run())

    def save_login(self, request_id, token, identity, fields):
        home=self.private_home(identity['team'],identity['owner'])
        with self.lock_for(home):
            return self.store.save_login(request_id,token,identity,fields)

    def save_code(self, request_id, token, identity, fields):
        home=self.private_home(identity['team'],identity['owner'])
        with self.lock_for(home):return self.store.save_code(request_id,token,identity,fields)

    async def disconnect(self, team, owner, handle):
        from agent.vault_store import VaultStore
        home = self.private_home(team,owner)
        if VaultStore(home/'vault').get_meta(handle) is None:raise AccessError('This saved account was not found.',404)
        self.store.cancel_owner(team,owner)
        # Native interruption prevents a concurrent owner turn reopening a browser
        # while its profiles are being removed. Other owners keep running.
        runner=getattr(self.policy.adapter,'gateway_runner',None)
        from gateway.session import SessionSource
        from gateway.config import Platform
        member=self.validate_member(team,owner)
        source=SessionSource(Platform.SLACK,member['dm_id'],user_id=owner,scope_id=team,profile=member['profile'])
        if runner is not None:
            from gateway.platforms.event import MessageEvent
            event=MessageEvent(text='/stop',source=source,user_id=owner)
            await runner._handle_stop_command(event)
        def remove():
            import shutil
            from seatbelt.context import Context
            from seatbelt.launcher import stop_chrome
            with self.lock_for(home):
                store = VaultStore(home/'vault')
                if store.get_meta(handle) is None:
                    raise AccessError('This saved account was not found.',404)
                if self.cloud_browser is not None:
                    turn=Binding(self,source,'disconnect','',home)
                    self.cloud_browser.stop(turn,purge=True)
                context = Context(home)
                # Reset all of this owner's browser sessions so federated-login
                # cookies cannot survive removal of the identity-provider login.
                for state in (home/'.clanker-execution').glob('chrome-*.json'):
                    value = json.loads(state.read_text())
                    stop_chrome(context,value['name'])
                shutil.rmtree(context.browser/'chromium',ignore_errors=False) if (context.browser/'chromium').exists() else None
                store.remove_item(handle)
        await asyncio.to_thread(remove)

    async def start(self):
        from .web import VaultWeb
        self.loop = asyncio.get_running_loop()
        from agent.secret_scope import build_profile_secret_scope
        if not build_profile_secret_scope(self.policy.home).get('CLANKER_SLACK_CLIENT_SECRET'):
            raise AccessError('Slack sign-in has not been configured.',503)
        self.web = VaultWeb(self,self.config)
        await self.web.start()
        async def acknowledge(ack):
            await ack()
        self.policy.adapter._app.action('clanker_vault_link')(acknowledge)

    async def close(self):
        for task in list(self.resume_tasks.values()):task.cancel()
        await asyncio.gather(*list(self.resume_tasks.values()),return_exceptions=True)
        await self.web.close()


def configured_service(policy):
    config = policy.home/'.clanker-vault'/'config.json'
    if not config.exists():
        return None
    settings = json.loads(config.read_text())
    if not settings.get('enabled'):
        return None
    if set(settings)-{'enabled','client_id','public_url','port'}:
        raise AccessError('The hosted vault configuration has unsupported options.',503)
    if not settings.get('client_id') or not settings.get('public_url'):
        raise AccessError('The hosted vault requires its public URL and Slack sign-in configuration.',503)
    return VaultService(policy,settings)

